// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

const N_ANIM = 200; // how long the whole animation lasts
const N_TRANSITION = N_ANIM/2; // how long a transition of 1 element lasts
const N_WAIT = 100; // how long the wait is between 2 animation phases
const N_FRAMES = 2*(N_ANIM+N_WAIT); // how long the whole loop lasts

const N_FRAMES_PATTERN = N_FRAMES/3; // how long the pattern animation loop is (the waves)

let rStep = 5;
let rMin = rStep*15;
let nSteps = 25;
let nDivs = 120;

let dots = [];

function setup() {
	createCanvas(550, 550);
	noStroke();

	let j0 = 0;
	for (let i = 0; i < nSteps; i++) {
		let r = rMin + i*rStep;
		let d1 = 2*rStep;
		let d2 = 2*r*sin(TAU/nDivs);
		let d3 = sqrt(sq(r-(r+rStep)*cos(TAU/nDivs)) + sq((r+rStep)*sin(TAU/nDivs)));
		let d4 = sqrt(sq(r-(r-rStep)*cos(TAU/nDivs)) + sq((r-rStep)*sin(TAU/nDivs)));
		let dMin = 2, dMax = min([d1, d2, d3, d4])*3/4;
		for (let j = j0; j < nDivs; j += 2) {
			let theta = j*TAU/nDivs;
			let x = width/2 + r*cos(theta), y = height/2 + r*sin(theta);
			dots.push({x: x, y: y, r: r, theta: theta, dMin: dMin, dMax: dMax});
		}
		j0 = 1-j0;
	}
}

function draw() {
	background(5);
	fill(250);
	let animBlock = (N_ANIM-N_TRANSITION)/(dots.length-1);

	for (let i = 0; i < dots.length; i++) {
		let t;
		let frameInCycle = frameCount%N_FRAMES;
		if (frameInCycle < N_WAIT) t = 0;
		else if (frameInCycle < N_WAIT + N_ANIM) {
			let startTransition = i*animBlock;
			let endTransition = startTransition + N_TRANSITION;
			let f = frameInCycle-N_WAIT;
			if (f < startTransition) t = 0;
			else if (f < endTransition) t = ((f-startTransition)/N_TRANSITION);
			else t = 1;
		} else if (frameInCycle < 2*N_WAIT + N_ANIM) t = 1;
		else {
			let startTransition = (dots.length-i-1)*animBlock;
			let endTransition = startTransition + N_TRANSITION;
			let f = frameInCycle-2*N_WAIT-N_ANIM;
			if (f < startTransition) t = 1;
			else if (f < endTransition) t = 1-((f-startTransition)/N_TRANSITION);
			else t = 0;
		}

		let {x, y, r, theta, dMin, dMax} = dots[i];
		let tPattern = (frameCount%N_FRAMES_PATTERN)/N_FRAMES_PATTERN;
		let val1 = (sin(TAU*tPattern - r/18 - 2*theta)+1)/2;
		let val2 = (sin(TAU*tPattern + r/18 - 2*theta)+1)/2;
		let val = lerp(val1, val2, t);
		val *= 1-sq(2*(r-rMin)/(rStep*nSteps)-1); // make it smaller when closer to the borders
		let d = map(val, 0, 1, dMin, dMax);
		circle(x, y, d);
	}
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
